          order='target_first', include_start=False, arrive='le'):
    rng=np.random.RandomState(seed)
    def nt(): return (rng.uniform(0,w), rng.uniform(0,h))
    def ns(): return rng.uniform(sr[0],sr[1])
    if order=='target_first': tgt=nt(); sp=ns()
    else: sp=ns(); tgt=nt()
    x,y=start
    tr=[(x,y)] if include_start else []
    n = num_steps-1 if include_start else num_steps
    for _ in range(n):
        dx=tgt[0]-x; dy=tgt[1]-y; dist=math.hypot(dx,dy)
